properties.query:
let windowSize = 1h;

// S105: Sybil Node Injection
let S105 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'sybil_node_join'
    | extend Stage = 'S105', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S102: Consensus Poisoning
let S102 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'consensus_poison'
    | extend Stage = 'S102', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S7: Imagery Hijack — 군집 임무 컨텍스트에서 UAVImagery_CL에 병기되는 SwarmId 필드
let S7 =
    UAVImagery_CL
    | where TimeGenerated > ago(windowSize)
    | where StreamEvent in ('unauthorized_access','feed_hijack')
    | extend Stage = 'S7', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S79: Off-hours C4I — 군집 임무 컨텍스트에서 UAVC4I_CL에 병기되는 SwarmId 필드
let S79 =
    UAVC4I_CL
    | where TimeGenerated > ago(windowSize)
    | where hourofday(TimeGenerated) >= 23 or hourofday(TimeGenerated) < 5
    | extend Stage = 'S79', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S105, S102, S7, S79
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| where StageCount >= 3
| extend CampaignType = "C25_합의전복_Sybil_포이즈닝_위조영상_C4I위조"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
